public inherited sharing class LogPurgeJob implements Schedulable {

    @TestVisible
    private static final Integer DEBUG_RETENTION_DAYS = 30;

    @TestVisible
    private static final Integer ERROR_RETENTION_DAYS = 180;

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext ctx) {
        deleteLogsOlderThan(DEBUG_RETENTION_DAYS, ERROR_RETENTION_DAYS);
    }

    public static Id scheduleNightly() {
        return System.schedule('Log purge (nightly)', '0 0 2 * * ?', new LogPurgeJob());
    }

    @TestVisible
    private static void deleteLogsOlderThan(Integer standardRetentionDays, Integer errorRetentionDays) {
        // One cutoff for everything (ERROR and non-ERROR alike): the longest retention.
        Datetime oldestKeptErrorCreatedDate = Datetime.now().addDays(-errorRetentionDays);
        // Cutoff for non-ERROR (and blank) levels: the shorter retention.
        Datetime oldestKeptOtherCreatedDate = Datetime.now().addDays(-standardRetentionDays);

        List<FB_Integration_Log__c> logsToDelete = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :oldestKeptErrorCreatedDate
               OR (CreatedDate < :oldestKeptOtherCreatedDate
                   AND (Level__c = null OR Level__c != 'ERROR'))
        ];

        // Database.delete is bulk-safe and only re-queries rows that actually fail
        // (mixed-DML / row-lock issues), which will not happen for this custom object.
        if (!logsToDelete.isEmpty()) {
            Database.delete(logsToDelete, false);
        }
    }
}
