public inherited with sharing class Opportunities extends fflib_SObjectDomain
{
    public Opportunities(List<Opportunity> records)
    {
        super(records);
    }

    public Opportunities(Map<Id, SObject> existingRecords, List<Opportunity> records)
    {
        super(existingRecords, records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities(sObjectList);
        }

        public fflib_SObjectDomain construct(Map<Id, SObject> existingRecords, List<SObject> sObjectList)
        {
            return new Opportunities((Map<Id, Opportunity>) existingRecords, (List<Opportunity>) sObjectList);
        }
    }

    public override void onValidate()
    {
        validateAmountNotNegative((List<Opportunity>) Records);
        validateAmountLockedOnWon((List<Opportunity>) Records);
    }

    /**
     * Rule 1: On insert and on update, Amount must not be negative.
     */
    private void validateAmountNotNegative(List<Opportunity> opportunities)
    {
        for (Opportunity opp : opportunities)
        {
            if (opp.Amount != null && opp.Amount < 0)
            {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }
    }

    /**
     * Rule 2: On update, an opportunity whose stage was already Closed Won before the
     * update cannot have its Amount changed. Closing as won (or any transition into
     * Closed Won) combined with an amount change in the same update is allowed.
     */
    private void validateAmountLockedOnWon(List<Opportunity> opportunities)
    {
        // Changed records map is only populated on update (original -> current).
        Map<Id, SObject> changedOldRecords = getChangedRecords().oldMap;
        if (changedOldRecords.isEmpty())
        {
            return; // insert context: rule does not apply
        }

        Map<Id, Opportunity> currentRecordsById = new Map<Id, Opportunity>((List<Opportunity>) Records);

        for (Id oppId : changedOldRecords.keySet())
        {
            Opportunity before = (Opportunity) changedOldRecords.get(oppId);
            Opportunity after = currentRecordsById.get(oppId);

            // Only lock amount when the record was already Closed Won before this update.
            if (before.StageName == 'Closed Won'
                && after.Amount != before.Amount)
            {
                error('Amount cannot change on a won opportunity.', after, Opportunity.Amount);
            }
        }
    }
}
