```apex
public inherited sharing class FollowUpTaskService {

    /**
     * Creates a follow-up Task for each Opportunity Id supplied.
     *
     * Returns the Ids of the opportunities whose Task could NOT be created
     * (empty set when every task was created successfully).
     *
     * Implementation note: a naive loop of `insert` statements inside try/catch
     * does NOT survive bulk load. In Apex, when a DML statement throws inside a
     * transaction, all previously created (uncommitted) rows in that transaction
     * are rolled back - so a single validation failure at row 200 would wipe out
     * the 199 tasks inserted before it. To get genuine per-record isolation we
     * use a single partial-success DML (Database.insert with allOrNone=false),
     * which returns a SaveResult per row and lets the remaining tasks persist
     * when one is rejected by a validation rule.
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // De-duplicate and keep only genuine Opportunity Ids.
        Set<Id> requestedIds = new Set<Id>();
        for (Id oppId : opportunityIds) {
            if (oppId != null && String.valueOf(oppId).startsWithIgnoreCase(Schema.Opportunity.SObjectType.getDescribe().getKeyPrefix())) {
                requestedIds.add(oppId);
            }
        }
        if (requestedIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // Single query for everything we need (name + owner) - avoids per-row queries.
        Map<Id, Opportunity> opportunitiesById = new Map<Id, Opportunity>(
            [
                SELECT Id, Name, OwnerId
                FROM Opportunity
                WHERE Id IN :requestedIds
            ]
        );

        // Build all tasks up front; no DML inside the loop.
        List<Task> tasksToInsert = new List<Task>();
        List<Id> opportunityIdByTaskIndex = new List<Id>();
        Date dueDate = Date.today().addDays(7);

        for (Id oppId : requestedIds) {
            Opportunity opp = opportunitiesById.get(oppId);
            if (opp == null) {
                // Opportunity does not exist (or is not visible) - report as failed.
                failedOpportunityIds.add(oppId);
                continue;
            }

            tasksToInsert.add(
                new Task(
                    WhatId = opp.Id,
                    OwnerId = opp.OwnerId,
                    Subject = 'Follow up: ' + opp.Name,
                    ActivityDate = dueDate,
                    Status = 'Not Started',
                    Priority = 'Normal'
                )
            );
            opportunityIdByTaskIndex.add(opp.Id);
        }

        if (tasksToInsert.isEmpty()) {
            return failedOpportunityIds;
        }

        // Partial-success insert: one DML call, per-record isolation.
        List<Database.SaveResult> saveResults = Database.insert(tasksToInsert, false);

        for (Integer i = 0; i < saveResults.size(); i++) {
            if (!saveResults[i].isSuccess()) {
                failedOpportunityIds.add(opportunityIdByTaskIndex[i]);
            }
        }

        return failedOpportunityIds;
    }
}
