/**
 * AccountCountrySync
 *
 * When an Account's BillingCountry changes (after update), update that
 * Account's Contacts whose MailingCountry is blank, or equal to the
 * Account's *previous* BillingCountry, so they follow the new HQ country.
 *
 * Deliberately untouched:
 *  - Contacts whose MailingCountry differs from the Account's previous
 *    BillingCountry (they work abroad) — not our job to move them.
 *  - Contacts of Accounts whose BillingCountry did not change.
 *
 * Bulk safety:
 *  - Exactly ONE SOQL per transaction, executed once, outside any loop,
 *    filtered to the Accounts in the trigger batch (AccountId IN :ids).
 *    We never query "all contacts" — 2.3M rows would blow both the SOQL
 *    50k-row limit and the 6MB synchronous heap limit.
 *  - No DML inside loops: a single Database.update at the end.
 *  - Skips contacts already matching the new country (smaller DML payload).
 *
 * Trigger context contract: must be called from an Account AFTER UPDATE
 * trigger (Trigger.oldMap supplies the previous BillingCountry).
 */
public with sharing class AccountCountrySync {

    /**
     * Simple static guard so that any Account-trigger re-entry caused by
     * downstream automation during this same transaction does not re-run
     * the sync. Reset at the start of each new execution context.
     */
    @TestVisible
    private static Boolean syncAlreadyRan = false;

    public static void handle(List<Account> newAccounts, Map<Id, Account> oldAccountsById) {
        if (syncAlreadyRan) {
            return;
        }
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }
        // From here on we rely on Trigger.oldMap having a matching entry;
        // that is guaranteed in an after-update context. Guard defensively anyway.
        if (oldAccountsById == null) {
            return;
        }

        // ------------------------------------------------------------------
        // Step 1: work out which accounts actually changed BillingCountry.
        // ------------------------------------------------------------------
        Set<Id> changedAccountIds = new Set<Id>();
        for (Account acc : newAccounts) {
            Account old = oldAccountsById.get(acc.Id);
            if (old == null) {
                continue;
            }
            String oldCountry = old.BillingCountry;
            String newCountry = acc.BillingCountry;
            if (isChanged(oldCountry, newCountry)) {
                changedAccountIds.add(acc.Id);
            }
        }

        if (changedAccountIds.isEmpty()) {
            return; // No BillingCountry changed — do nothing at all.
        }

        // ------------------------------------------------------------------
        // Step 2: ONE query for the contacts of those accounts, executed
        // once, outside any loop. Bulk-safe and heap-safe.
        // ------------------------------------------------------------------
        Map<Id, List<Contact>> contactsByAccountId = new Map<Id, List<Contact>>();
        for (Contact c : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
        ]) {
            List<Contact> bucket = contactsByAccountId.get(c.AccountId);
            if (bucket == null) {
                bucket = new List<Contact>();
                contactsByAccountId.put(c.AccountId, bucket);
            }
            bucket.add(c);
        }

        // ------------------------------------------------------------------
        // Step 3: decide which contacts follow the new HQ country.
        // ------------------------------------------------------------------
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Account acc : newAccounts) {
            if (!changedAccountIds.contains(acc.Id)) {
                continue;
            }
            String newCountry = acc.BillingCountry;
            String oldCountry = oldAccountsById.get(acc.Id).BillingCountry;

            List<Contact> contacts = contactsByAccountId.get(acc.Id);
            if (contacts == null) {
                continue; // Account has no contacts — nothing to do.
            }

            for (Contact c : contacts) {
                String mail = c.MailingCountry;
                if (isBlankOrWhitespace(mail)) {
                    // Blank mailing country: contact follows HQ.
                    contactsToUpdate.add(new Contact(
                        Id = c.Id,
                        MailingCountry = newCountry
                    ));
                } else if (oldCountry != null && isSameCountry(mail, oldCountry)) {
                    // Contact's mailing country equals the account's
                    // previous billing country: contact follows HQ.
                    // Skip if it already equals the new value (no-op).
                    if (!isSameCountry(mail, newCountry)) {
                        contactsToUpdate.add(new Contact(
                            Id = c.Id,
                            MailingCountry = newCountry
                        ));
                    }
                }
                // else: contact lives abroad — leave it alone.
            }
        }

        // ------------------------------------------------------------------
        // Step 4: one bulk DML.
        // ------------------------------------------------------------------
        if (!contactsToUpdate.isEmpty()) {
            // allOrNone = true (default): a partial HQ move is worse than a
            // clean failure the MDM retry can handle. Flip to
            // Database.update(contactsToUpdate, false) if partial success is
            // ever preferred.
            update contactsToUpdate;
            syncAlreadyRan = true;
        }
    }

    /**
     * True if the two country values represent a real change.
     * Null-safe; case-insensitive but value-preserving (we never rewrite the
     * literal text — picklist API values must match exactly).
     */
    @TestVisible
    private static Boolean isChanged(String oldCountry, String newCountry) {
        if (oldCountry == null && newCountry == null) {
            return false;
        }
        if (oldCountry == null || newCountry == null) {
            return true;
        }
        return !oldCountry.equalsIgnoreCase(newCountry);
    }

    /**
     * True when the two values refer to the same country (case-insensitive,
     * whitespace-trimmed). Null never equals null here because a null /
     * blank contact MailingCountry is handled by the "blank" branch instead.
     */
    @TestVisible
    private static Boolean isSameCountry(String a, String b) {
        if (a == null || b == null) {
            return false;
        }
        String ta = a.trim();
        String tb = b.trim();
        return !ta.isEmpty() && !tb.isEmpty() && ta.equalsIgnoreCase(tb);
    }

    /**
     * "Blank" for our purposes: null, empty, or whitespace-only. This mirrors
     * what a user sees as an empty field; isBlank() alone would not catch a
     * string of spaces.
     */
    @TestVisible
    private static Boolean isBlankOrWhitespace(String value) {
        return value == null || value.trim().isEmpty();
    }
}
