import { LightningElement, api, track } from 'lwc';

const NAVIGATION_KEYS = new Set([
    'ArrowDown',
    'ArrowUp',
    'Home',
    'End',
    'Enter',
    ' ',
]);

export default class StatusListbox extends LightningElement {
    @api label = '';

    @track _options = [];
    @track activeIndex = 0;
    @track selectedValue = '';

    _value = '';

    @api
    get options() {
        return this._options;
    }
    set options(value) {
        this._options = Array.isArray(value) ? value : [];
        this.normalize();
    }

    @api
    get value() {
        return this._value;
    }
    set value(value) {
        this._value = value == null ? '' : value;
        this.normalize();
    }

    connectedCallback() {
        this.normalize();
    }

    // Keeps activeIndex in sync with the current value:
    // active option = selected option, or first option if nothing is selected.
    normalize() {
        const count = this._options.length;
        if (count === 0) {
            this.activeIndex = 0;
            return;
        }
        const selectedIndex = this._options.findIndex(
            (option) => option.value === this._value
        );
        if (selectedIndex >= 0) {
            this.activeIndex = selectedIndex;
        } else {
            this.activeIndex = 0;
            this.selectedValue = '';
        }
    }

    get renderedOptions() {
        return this._options.map((option, index) => ({
            ...option,
            id: this.optionId(index),
            isSelected: option.value === this.selectedValue,
        }));
    }

    get activeDescendantId() {
        return this._options.length > 0
            ? this.optionId(this.activeIndex)
            : null;
    }

    optionId(index) {
        return `${this.resolveElementId()}-option-${index}`;
    }

    resolveElementId() {
        // Stable per-instance id for aria-activedescendant references.
        if (this._elementId == null) {
            this._elementId =
                this.template.host.dataset.elementId ||
                'status-listbox-' + Math.random().toString(36).slice(2, 10);
        }
        return this._elementId;
    }

    get selectedValue() {
        return this._selectedValue;
    }
    set selectedValue(value) {
        this._selectedValue = value;
    }

    handleKeyDown(event) {
        if (!NAVIGATION_KEYS.has(event.key)) {
            // Tab and every other key keep their default behaviour.
            return;
        }
        event.preventDefault();

        const count = this._options.length;
        if (count === 0) {
            return;
        }

        switch (event.key) {
            case 'ArrowDown':
                this.activeIndex = Math.min(this.activeIndex + 1, count - 1);
                break;
            case 'ArrowUp':
                this.activeIndex = Math.max(this.activeIndex - 1, 0);
                break;
            case 'Home':
                this.activeIndex = 0;
                break;
            case 'End':
                this.activeIndex = count - 1;
                break;
            case 'Enter':
            case ' ':
                this.selectIndex(this.activeIndex);
                break;
            default:
                break;
        }
    }

    handleClick(event) {
        const item = event.currentTarget;
        const value = item.dataset.value;
        const index = this._options.findIndex(
            (option) => option.value === value
        );
        if (index >= 0) {
            this.activeIndex = index;
            this.selectIndex(index);
        }
    }

    selectIndex(index) {
        const option = this._options[index];
        if (!option || option.value === this.selectedValue) {
            // Already selected: no event dispatched.
            return;
        }
        this.selectedValue = option.value;
        this._value = option.value;
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value: option.value },
            })
        );
    }
}
