public with sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    /**
     * Creates one Enhanced Recurring Donation per request and returns the new
     * Ids in request order.
     *
     * Validation happens before any DML so nothing is inserted when any
     * request is invalid. Uses a single SOQL query and a single DML
     * statement regardless of request count.
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return new List<Id>();
        }

        validate(requests);

        List<npe03__Recurring_Donation__c> rdToInsert = new List<npe03__Recurring_Donation__c>();
        for (GiftRequest req : requests) {
            rdToInsert.add(buildRecurringDonation(req));
        }

        insert rdToInsert;

        List<Id> result = new List<Id>();
        for (npe03__Recurring_Donation__c rd : rdToInsert) {
            result.add(rd.Id);
        }
        return result;
    }

    private static void validate(List<GiftRequest> requests) {
        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest req = requests[i];
            if (req.contactId == null) {
                throw new RecurringGiftException('Request at index ' + i + ': contact is required.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new RecurringGiftException('Request at index ' + i + ': amount must be a positive number.');
            }
            if (req.dayOfMonth == null || req.dayOfMonth < 1 || req.dayOfMonth > 31) {
                throw new RecurringGiftException('Request at index ' + i + ': dayOfMonth must be between 1 and 31.');
            }
            if (req.startDate == null) {
                throw new RecurringGiftException('Request at index ' + i + ': startDate is required.');
            }
        }
    }

    private static npe03__Recurring_Donation__c buildRecurringDonation(GiftRequest req) {
        Boolean fixedLength = (req.installments != null && req.installments > 0);

        npe03__Recurring_Donation__c rd = new npe03__Recurring_Donation__c(
            npe03__Contact__c = req.contactId,
            npe03__Amount__c = req.amount,
            npe03__Installment_Period__c = 'Monthly',
            npe03__Schedule_Type__c = fixedLength ? 'Fixed' : 'Open',
            npe03__Open_Ended_Status__c = fixedLength ? null : 'Open',
            npe03__Date_Established__c = req.startDate,
            npe03__Next_Payment_Date__c = req.startDate,
            npsp__RecurringType__c = 'Regular',
            npsp__InstallmentFrequency__c = 1,
            npsp__Day_of_Month__c = req.dayOfMonth,
            npsp__Always_Use_Last_Day_Of_Month__c = (req.dayOfMonth == 31),
            npsp__StartDate__c = req.startDate,
            npsp__Status__c = 'Active',
            npsp__PaymentMethod__c = req.paymentMethod
        );

        if (fixedLength) {
            rd.put('npe03__Installments__c', req.installments);
            rd.put('npsp__EndDate__c', calculateEndDate(req.startDate, req.installments));
        }

        return rd;
    }

    /**
     * Estimates the schedule end date for fixed-length schedules so the
     * EndDate field reflects the full planned series. NPSP regenerates the
     * installment opportunities itself from Day of Month / frequency.
     */
    private static Date calculateEndDate(Date startDate, Integer installments) {
        if (installments <= 1) {
            return startDate;
        }
        // (installments - 1) months after startDate; use the 1st of that
        // month then re-apply the requested day so short months roll into
        // the next month, matching NPSP's own schedule generation.
        Integer year = startDate.year();
        Integer month = startDate.month() + (installments - 1);
        year += (month - 1) / 12;
        month = ((month - 1) % 12) + 1;

        Date lastScheduledMonth = Date.newInstance(year, month, 1);
        Date candidate = lastScheduledMonth.addDays(Math.min(startDate.day(), daysInMonth(year, month)) - 1);
        while (candidate.day() != startDate.day()
                && candidate < lastScheduledMonth.addDays(daysInMonth(year, month) - 1)) {
            candidate = candidate.addDays(1);
        }
        return candidate;
    }

    private static Integer daysInMonth(Integer year, Integer month) {
        if (month == 2) {
            Boolean isLeap = (Math.mod(year, 4) == 0 && Math.mod(year, 100) != 0) || Math.mod(year, 400) == 0;
            return isLeap ? 29 : 28;
        }
        if (month == 4 || month == 6 || month == 9 || month == 11) {
            return 30;
        }
        return 31;
    }
}
