/**
 * @description Creates an onboarding Task for the owner of each newly created
 * Account whose Type is a customer type ("Customer - Direct" or
 * "Customer - Channel").
 *
 * Runs in the after insert context so that Account Ids are available for the
 * Task WhatId, and so the trigger has no DML of its own on the Account object.
 *
 * Bulk-safe: collects all qualifying tasks and inserts them with a single DML
 * statement per trigger execution. No DML is performed when no account
 * qualifies.
 *
 * Registered via Trigger_Action__mdt "TA_Account_CreateOnboardingTask"
 * (Order 10) on the Account sObject_Trigger_Setting__mdt After Insert context.
 */
public inherited sharing class TA_Account_CreateOnboardingTask implements TriggerAction.AfterInsert {

    private static final String REQUIRED_SUBJECT = 'Onboard new customer';
    private static final String TASK_STATUS = 'Not Started';
    private static final String TASK_PRIORITY = 'Normal';
    private static final Integer DUE_DATE_OFFSET_DAYS = 7;
    private static final Set<String> ONBOARDING_ACCOUNT_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    /**
     * @description Inserts one onboarding Task per qualifying new Account.
     * @param triggerNew the list of Accounts being inserted
     */
    public void afterInsert(List<SObject> triggerNew) {
        List<Task> tasksToInsert = new List<Task>();

        for (SObject record : triggerNew) {
            Account account = (Account) record;
            if (isOnboardingAccount(account)) {
                tasksToInsert.add(buildOnboardingTask(account));
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }

    /**
     * @description Determines whether an Account qualifies for an onboarding Task.
     * @param account the Account to evaluate
     * @return true when the Account Type is a customer type
     */
    private Boolean isOnboardingAccount(Account account) {
        String accountType = account.Type;
        return accountType != null && ONBOARDING_ACCOUNT_TYPES.contains(accountType);
    }

    /**
     * @description Builds the onboarding Task for a single Account.
     * @param account the qualifying Account
     * @return the Task to insert
     */
    private Task buildOnboardingTask(Account account) {
        Task onboardingTask = new Task(
            Subject = REQUIRED_SUBJECT,
            WhatId = account.Id,
            OwnerId = account.OwnerId,
            Status = TASK_STATUS,
            Priority = TASK_PRIORITY
        );
        onboardingTask.ActivityDate = Date.today().addDays(DUE_DATE_OFFSET_DAYS);
        return onboardingTask;
    }
}
