```apex
/**
 * Trigger Action (after insert, after update) for the Trigger Actions Framework.
 *
 * Collects the Ids of the Opportunities of the current DML operation that must be
 * pushed to the ERP:
 *   - after insert: every record of the operation.
 *   - after update: every record whose StageName changed.
 *
 * The Ids are buffered in OpportunityErpSyncFinalizer, which is invoked by the
 * framework once at the end of each DML operation and enqueues exactly one
 * OpportunityErpSyncJob per operation, carrying every collected Id. Trigger chunks
 * of the same DML statement (e.g. 200 + 50) accumulate into the same buffer, while
 * separate DML statements produce separate buffers (the finalizer drains it), and
 * therefore separate jobs.
 */
public with sharing class TA_Opportunity_CollectForErpSync
        implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> idsToSync = new Set<Id>();
        for (SObject record : triggerNew) {
            idsToSync.add(record.Id);
        }
