/**
 * Trigger Actions Framework action for Opportunity (after insert, after update).
 *
 * Collects the Ids of the opportunities of the current DML operation that must be
 * pushed to the ERP:
 *   - after insert: every opportunity of the operation.
 *   - after update: every opportunity whose StageName changed.
 *
 * The Ids are buffered in OpportunityErpSyncFinalizer. The framework invokes that
 * finalizer once at the end of each DML operation, so all trigger chunks of a single
 * DML statement (for example 200 + 50 records) accumulate into the same buffer and
 * produce exactly one OpportunityErpSyncJob, while each separate DML statement of the
 * same transaction gets its own buffer and therefore its own job.
 */
public with sharing class TA_Opportunity_CollectForErpSync implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> idsToSync = new Set<Id>();
        for (SObject record : triggerNew) {
            idsToSync.add(record.Id);
        }
        OpportunityErpSyncFinalizer.collectOpportunityIds(idsToSync);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Opportunity> newOpportunities = (List<Opportunity>) triggerNew;
        List<Opportunity> oldOpportunities = (List<Opportunity>) triggerOld;
        Set<Id> idsToSync = new Set<Id>();
        for (Integer i = 0; i < newOpportunities.size(); i++) {
            if (newOpportunities[i].StageName != oldOpportunities[i].StageName) {
                idsToSync.add(newOpportunities[i].Id);
            }
        }
        OpportunityErpSyncFinalizer.collectOpportunityIds(idsToSync);
    }
}
```

